=== useDrawerMenuState.ts ===
import { createContext, useContext } from 'react';
import type { HeaderNavItemEntry } from 'app/types/contentful';

export type DrawerMenuStateContextValue = {
  /** The L1 item currently drilled into, or `null` at L1. Only meaningful while `isDrilledIn`
   * is true — DrawerMenu reads this to know which item's columns to render as its L2 panel. */
  activeItem: HeaderNavItemEntry | null;
  /** Whether the drawer is showing the L2 (drilled-in) panel rather than the L1 root list. */
  isDrilledIn: boolean;
  /** Called by DrawerMenu when the shopper taps an L1 row that has columns (drills to L2). */
  drillInto: (item: HeaderNavItemEntry) => void;
  /** Called by DrawerMenu whenever its own `isOpen` prop (owned by base `_app`'s
   * `useDisclosure`, not by this hook — see useHeaderMenuExpandedState's own comment)
   * transitions to false. Keeps the header shell's chrome state in sync no matter how the
   * physical drawer actually closed (LeftBar/RightBar's own close controls, Escape, or an
   * overlay click all eventually flow through here). */
  notifyClosed: () => void;
  /** DrawerMenu registers its real `onClose` prop (the one it receives directly from base
   * `_app`) here on mount, so the header shell's LeftBar 'X' / RightBar close-icon — which
   * have no `onClose` prop of their own — can trigger the actual Chakra `<Drawer>` close.
   * Pass `null` to unregister on unmount. */
  registerCloseHandler: (fn: (() => void) | null) => void;
};

const noop = () => undefined;

/**
 * Static default so DrawerMenu (and its presentational view) can still render standalone in
 * Storybook/Vitest without a header-mounted Provider — same graceful-degradation shape as
 * useUiCopy (see .claude/rules/components.md's Context-backed-hook exception). A story/test
 * that needs to exercise real drill-in/close-registration behaviour should wrap with
 * `DrawerMenuStateContext.Provider` instead of relying on this default.
 */
export const DEFAULT_DRAWER_MENU_STATE: DrawerMenuStateContextValue = {
  activeItem: null,
  isDrilledIn: false,
  drillInto: noop,
  notifyClosed: noop,
  registerCloseHandler: noop,
};

/**
 * Shares mobile drawer L1↔L2 drill state between the header shell (`header/index.tsx`, via
 * `useHeaderMenuExpandedState`) and `DrawerMenu`, which base `_app.jsx` renders as one of
 * Header's `children` (redirected to our override through the `ccExtensibility` resolver) —
 * not a component Header instantiates directly. Context is the tool for this rather than a
 * prop, since Header cannot see through whatever wrapper elements (`HideOnDesktop`, etc.)
 * base `_app.jsx` nests `<DrawerMenu>` inside.
 */
export const DrawerMenuStateContext = createContext<DrawerMenuStateContextValue | undefined>(undefined);

/**
 * Consumed by `DrawerMenu` to read/report L1↔L2 drill state that's actually owned by the
 * header shell. Degrades to `DEFAULT_DRAWER_MENU_STATE` with no Provider mounted, matching
 * useUiCopy's pattern — see that hook's own JSDoc for the reasoning.
 *
 * @returns the current drawer menu state/actions — see DrawerMenuStateContextValue.
 */
export const useDrawerMenuState = (): DrawerMenuStateContextValue =>
  useContext(DrawerMenuStateContext) ?? DEFAULT_DRAWER_MENU_STATE;

