import React, { useEffect, useRef } from 'react';
import {
  Box,
  Center,
  Drawer,
  DrawerBody,
  DrawerContent,
  DrawerOverlay,
  Image,
  Spinner,
  Text,
  useMultiStyleConfig,
} from '@salesforce/retail-react-app/app/components/shared/ui';
import { useCustomerType } from '@salesforce/commerce-sdk-react';
import { noop } from '@salesforce/retail-react-app/app/utils/utils';
import { DRAWER_BODY_SX, DRAWER_CONTENT_SX, DRAWER_OVERLAY_SX } from './drawer-menu.css';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
import { useUiCopy } from 'app/hooks/useUiCopy';
import { useHeaderNav } from 'app/hooks/useHeaderNav';
import { useDrawerMenuState } from 'app/hooks/useDrawerMenuState';
import { resolveImageEntry } from 'app/utils/resolveImageEntry';
import type { HeaderNavItemEntry, NavGroupEntry } from 'app/types/contentful';

const SIGN_IN_HREF = '/login';
const WISHLIST_HREF = '/account/wishlist';
const ACCOUNT_HREF = '/account';

