        <Divider colorScheme="gray" />
        <Button variant="unstyled" {...headerStyles.signout} isDisabled={isSigningOut}>
          <chakra.div __css={styles.signoutRow}>
            <SignoutIcon aria-hidden={true} boxSize={5} {...headerStyles.signoutIcon} />
            <Text as="span" {...headerStyles.signoutText}>
              {t('header.popover.action.log_out', 'Log out')}
            </Text>
          </chakra.div>
        </Button>
      </PopoverFooter>
    </PopoverContent>
  </Popover>
) : (
  // audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists.
  <IconButtonWithRegistration
    aria-label={t('header.button.assistive_msg.my_account', 'My Account')}
    icon={<ZimmIcon type="profile" size="lg" aria-hidden={true} />}
    variant="unstyled"
    width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
    height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
    minWidth="unset"
    display="flex"
    justifyContent="center"
    alignItems="center"
    borderRadius="999px"
    overflow="clip"
    onClick={onMyAccountClick}
    onMouseOver={onAccountMenuOpen}
  />
)}

{/* Wishlist icon — audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists. */}
<IconButtonWithRegistration
  aria-label={t('header.button.assistive_msg.wishlist', 'Wishlist')}
  icon={<ZimmIcon type="wishlist" size="lg" aria-hidden={true} />}
  variant="unstyled"
  width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
  height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
  minWidth="unset"
  display="flex"
  justifyContent="center"
  alignItems="center"
  borderRadius="999px"
  overflow="clip"
  onClick={onWishlistClick}
/>

{/* Bag icon — audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists. */}
<IconButton
  aria-label={t(
    'header.button.assistive_msg.my_cart_with_num_items',
    'My cart, number of items: {numItems}',
    {
      numItems: totalItems,
    },
  )}
  icon={
    <>
      <ZimmIcon type="bag" size="lg" aria-hidden={true} />
      {hasBasket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
    </>
  }
  variant="unstyled"
  width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
  height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
